def aplana(datos: list) -> list:
    def _flatten(obj):
        if isinstance(obj, (list, tuple)):
            for item in obj:
                yield from _flatten(item)
        else:
            yield obj
    return list(_flatten(datos))

import csv

def parsear_ventas(texto: str) -> list[dict]:
    # Dividir el texto en líneas (soporta tanto \n como \r\n)
    lines = texto.splitlines()

    # Si no hay líneas, devolver lista vacía
    if not lines:
        return []

    # Encontrar la primera línea no vacía como cabecera
    header_line = None
    data_start = 0
    for i, line in enumerate(lines):
        if line.strip() != '':
            header_line = line
            data_start = i + 1
            break

    # Si no se encontró cabecera, devolver lista vacía
    if header_line is None:
        return []

    # Validar que la cabecera sea exactamente la esperada
    expected_header = "fecha,producto,cantidad,precio"
    if header_line.strip() != expected_header:
        raise ValueError("Cabecera incorrecta")

    result = []

    # Procesar cada línea de datos
    for line in lines[data_start:]:
        stripped = line.strip()
        # Ignorar líneas vacías o solo con espacios
        if not stripped:
            continue

        # Parsear la fila usando el módulo csv para manejar campos entre comillas
        try:
            reader = csv.reader([stripped])
            row = next(reader)
        except Exception:
            raise ValueError("Error al parsear fila")

        # Cada fila debe tener exactamente 4 campos
        if len(row) != 4:
            raise ValueError("Fila con número de campos incorrecto")

        fecha, producto, cantidad_str, precio_str = row

        # Validar 'cantidad': debe ser un entero y no negativo
        try:
            cantidad = int(cantidad_str)
        except ValueError:
            raise ValueError("cantidad no es un entero")
        if cantidad < 0:
            raise ValueError("cantidad negativa")

        # Validar 'precio': debe ser un número
        try:
            precio = float(precio_str)
        except ValueError:
            raise ValueError("precio no es un número")

        result.append({
            "fecha": fecha,
            "producto": producto,
            "cantidad": cantidad,
            "precio": precio
        })

    return result

import re

def parsear_fecha(texto: str) -> str:
    # Mapa de nombres de meses a números
    meses = {
        "enero": 1, "febrero": 2, "marzo": 3, "abril": 4,
        "mayo": 5, "junio": 6, "julio": 7, "agosto": 8,
        "septiembre": 9, "octubre": 10, "noviembre": 11, "diciembre": 12
    }

    def es_fecha_valida(año: int, mes: int, día: int) -> bool:
        # Días según el mes
        if mes in (2, 4, 6, 9, 11):
            max_día = 30
        elif mes == 2:
            # Año bisiesto
            if (año % 400 == 0) or (año % 4 == 0 and año % 100 != 0):
                max_día = 29
            else:
                max_día = 28
        else:
            max_día = 31
        return 1 <= día <= max_día

    # Eliminar espacios al principio y final
    texto = texto.strip()

    # Formato 1: AAAA-MM-DD
    m = re.fullmatch(r'(\d{4})-(\d{2})-(\d{2})', texto)
    if m:
        año, mes, día = map(int, m.groups())
        if 1 <= mes <= 12 and es_fecha_valida(año, mes, día):
            return f"{año:04d}-{mes:02d}-{día:02d}"
        else:
            raise ValueError("Fecha inválida")

    # Formato 2: DD/MM/AAAA
    m = re.fullmatch(r'(\d{2})/(\d{2})/(\d{4})', texto)
    if m:
        día, mes, año = map(int, m.groups())
        if 1 <= mes <= 12 and es_fecha_valida(año, mes, día):
            return f"{año:04d}-{mes:02d}-{día:02d}"
        else:
            raise ValueError("Fecha inválida")

    # Formato 3: D de MES de AAAA
    m = re.fullmatch(r'(\d{1,2})\s+de\s+([A-Za-z]+)\s+de\s+(\d{4})', texto)
    if m:
        día_str, mes_nombre, año = m.groups()
        día = int(día_str)
        mes = meses.get(mes_nombre.lower())
        if mes is None or not (1 <= mes <= 12) or not es_fecha_valida(int(año), mes, día):
            raise ValueError("Fecha inválida")
        return f"{int(año):04d}-{mes:02d}-{día:02d}"

    # Si no coincide con ningún formato
    raise ValueError("Formato no reconocido")

def promedio_movil(valores: list[float], ventana: int) -> list[float]:
    if ventana <= 0 or ventana > len(valores):
        return []
    resultado = []
    for i in range(len(valores) - ventana + 1):
        resultado.append(sum(valores[i:i + ventana]) / ventana)
    return resultado

from collections import OrderedDict


class CacheLRU:
    def __init__(self, capacidad: int):
        if capacidad < 0:
            raise ValueError("Capacidad no puede ser negativa")
        self.capacidad = capacidad
        self._datos = OrderedDict()

    def get(self, clave):
        if clave not in self._datos:
            return None
        # Marcar como recientemente usado
        self._datos.move_to_end(clave)
        return self._datos[clave]

    def put(self, clave, valor):
        if self.capacidad <= 0:
            # No se puede almacenar nada en una caché de capacidad cero o negativa
            return
        if clave in self._datos:
            # Actualizar el valor y mover al final (más reciente)
            self._datos[clave] = valor
            self._datos.move_to_end(clave)
        else:
            # Si la caché está llena, descartar el elemento menos reciente
            if len(self._datos) >= self.capacidad:
                self._datos.popitem(last=False)
            self._datos[clave] = valor

    def __len__(self):
        return len(self._datos)
